sub validate_input {
    my @inputs = @_;
    foreach my $input (@inputs) {
        if (defined $input && ref $input eq 'Str' && length($input) > 100) {
            return $input;
        } else {
            print "Invalid input: $input\n";
            return undef;
        }
    }
    return @inputs;
}
