    using System;

    public class NetworkHack
    {
        private Dictionary<string, string> ports = new Dictionary<string, string>();

        public void HackIntoNetwork(string target, int maxPort = 1024)
        {
            Console.WriteLine($"You've connected to {target}...");

            for (int port = 0; port <= maxPort; port++)
            {
                string portString = port.ToString().PadLeft(2, '0');

                // Simulating a 'listening' process
                Thread.Sleep(500);

                if (IsPortOpen(portString))
                {
                    Console.WriteLine($"Port {port} is open!");
                    // Store the open port in a dictionary
                    ports[portString] = true;
                }
            }

            Console.WriteLine("Reconnaissance time!");
            FindAndDisplayOpenPorts(target);

            Console.WriteLine("End of hack");
            Console.ReadLine();
        }

        public bool IsPortOpen(string portString)
        {
            // Simulating a check if a port is open
            Random rand = new Random();
            string[] numbers = portString.Split(' ');

            if (numbers.Length == 1 && int.TryParse(numbers[0], out int num))
            {
                int assignedPort = num;
                Console.WriteLine($"Assigned port # {assignedPort} for known open port... {portString}");

                return true;
            }
            else
            {
                Console.WriteLine($"Unknown port {portString}");
                return false;
            }
        }

        public void FindAndDisplayOpenPorts(string target)
        {
            // Simulating a search for open ports on the target network
            int numPortsToScan = 1000;
            Random rand = new Random();

            for (int i = 0; i < numPortsToScan; i++)
            {
                string portString = GetRandomPort();
                Console.WriteLine($"Scanning port {portString}... ");
                IsPortOpen(portString);
            }
        }

        public string GetRandomPort()
        {
            string[] numbers = Enumerable.Range(8000, 10000).Select(i => i.ToString() + "00").ToArray();
            Random rand = new Random();
            return numbers[rand.Next(numbers.Length)];
        }
    }
}
